#include <stdio.h>

int solution(int H, int U, int D) {
    int answer = 0;
    int height = 0;
    while (1) {
        answer++;
        height += U;
        if (height >= H) {
            break;
        }
        height -= D;
    }
    return answer;
}

problems.inputCheck:
def valid(H, U, D):
    if not all(type(x) is int for x in (H, U, D)):
        return False
    return 10 <= H <= 10000 and 1 <= U <= 1000 and 1 <= D < U

